function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    const roof = total;

    const bricks = grid.map(row => row.slice());

    for (const [r, c] of hits) {
        if (bricks[r][c] === 1) {
            bricks[r][c] = 0;
        }
    }

    const parent = new Int32Array(total + 1);
    const size = new Int32Array(total + 1);

    for (let i = 0; i <= total; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    const index = (r: number, c: number): number => r * n + c;

    const find = (x: number): number => {
        let root = x;
        while (parent[root] !== root) {
            root = parent[root];
        }

        while (parent[x] !== x) {
            const next = parent[x];
            parent[x] = root;
            x = next;
        }

        return root;
    };

    const union = (a: number, b: number): void => {
        let rootA = find(a);
        let rootB = find(b);

        if (rootA === rootB) return;

        if (size[rootA] < size[rootB]) {
            const temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    };

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (bricks[r][c] !== 1) continue;

            const id = index(r, c);

            if (r === 0) {
                union(id, roof);
            }

            if (r + 1 < m && bricks[r + 1][c] === 1) {
                union(id, index(r + 1, c));
            }

            if (c + 1 < n && bricks[r][c + 1] === 1) {
                union(id, index(r, c + 1));
            }
        }
    }

    const result = new Array<number>(hits.length).fill(0);
    const dirs = [-1, 0, 1, 0, 0, -1, 0, 1];

    for (let i = hits.length - 1; i >= 0; i--) {
        const [r, c] = hits[i];

        if (grid[r][c] === 0) {
            result[i] = 0;
            continue;
        }

        const before = size[find(roof)];

        bricks[r][c] = 1;
        const id = index(r, c);

        if (r === 0) {
            union(id, roof);
        }

        for (let d = 0; d < dirs.length; d += 2) {
            const nr = r + dirs[d];
            const nc = c + dirs[d + 1];

            if (
                nr >= 0 &&
                nr < m &&
                nc >= 0 &&
                nc < n &&
                bricks[nr][nc] === 1
            ) {
                union(id, index(nr, nc));
            }
        }

        const after = size[find(roof)];
        result[i] = Math.max(0, after - before - 1);
    }

    return result;
};
