/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function isCousins(root: TreeNode | null, x: number, y: number): boolean {
    if (root === null) return false;

    const queue: Array<[TreeNode, TreeNode | null]> = [[root, null]];
    let head = 0;

    while (head < queue.length) {
        const levelSize = queue.length - head;
        let xParent: TreeNode | null | undefined = undefined;
        let yParent: TreeNode | null | undefined = undefined;

        for (let i = 0; i < levelSize; i++) {
            const [node, parent] = queue[head++];

            if (node.val === x) xParent = parent;
            if (node.val === y) yParent = parent;

            if (node.left !== null) queue.push([node.left, node]);
            if (node.right !== null) queue.push([node.right, node]);
        }

        if (xParent !== undefined || yParent !== undefined) {
            return xParent !== undefined && yParent !== undefined && xParent !== yParent;
        }
    }

    return false;
};
