class FenwickTree {
    private tree: number[];
    private size: number;

    constructor(size: number) {
        this.size = size;
        this.tree = new Array(size + 2).fill(0);
    }

    add(index: number, delta: number): void {
        while (index <= this.size) {
            this.tree[index] += delta;
            index += index & -index;
        }
    }

    query(index: number): number {
        let sum = 0;
        while (index > 0) {
            sum += this.tree[index];
            index -= index & -index;
        }
        return sum;
    }

    kth(k: number): number {
        let index = 0;
        let bit = 1;
        while ((bit << 1) <= this.size) bit <<= 1;

        while (bit > 0) {
            const next = index + bit;
            if (next <= this.size && this.tree[next] < k) {
                index = next;
                k -= this.tree[next];
            }
            bit >>= 1;
        }

        return index + 1;
    }
}

