function maximumBinaryString(binary: string): string {
    const n = binary.length;
    let firstZero = -1;
    let zeroCount = 0;

    for (let i = 0; i < n; i++) {
        if (binary[i] === '0') {
            if (firstZero === -1) firstZero = i;
            zeroCount++;
        }
    }

    if (zeroCount <= 1) return binary;

    const zeroPosition = firstZero + zeroCount - 1;
    const result = new Array<string>(n).fill('1');
    result[zeroPosition] = '0';

    return result.join('');
}
