function maxSumTwoNoOverlap(nums: number[], firstLen: number, secondLen: number): number {
    const n = nums.length;
    const prefix: number[] = new Array(n + 1).fill(0);

    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    const sum = (start: number, len: number): number => {
        return prefix[start + len] - prefix[start];
    };

    const solve = (leftLen: number, rightLen: number): number => {
        let bestLeft = -Infinity;
        let bestTotal = -Infinity;

        for (let rightStart = leftLen; rightStart <= n - rightLen; rightStart++) {
            const leftStart = rightStart - leftLen;
            bestLeft = Math.max(bestLeft, sum(leftStart, leftLen));
            bestTotal = Math.max(bestTotal, bestLeft + sum(rightStart, rightLen));
        }

        return bestTotal;
    };

    return Math.max(
        solve(firstLen, secondLen),
        solve(secondLen, firstLen)
    );
};
