function minDays(n: number): number {
    const memo = new Map<number, number>();

    const dp = (x: number): number => {
        if (x <= 1) return x;
        if (memo.has(x)) return memo.get(x)!;

        const by2 = (x % 2) + 1 + dp(Math.floor(x / 2));
        const by3 = (x % 3) + 1 + dp(Math.floor(x / 3));
        const ans = Math.min(by2, by3);

        memo.set(x, ans);
        return ans;
    };

    return dp(n);
}
