    const MOD = 1000000007;
    const MOD_BIG = BigInt(MOD);
    const n = nums.length;

    const comb: number[][] = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));

    for (let i = 0; i <= n; i++) {
        comb[i][0] = 1;
        comb[i][i] = 1;
        for (let j = 1; j < i; j++) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
        }
    }

    const mulMod = (a: number, b: number): number => {
        return Number((BigInt(a) * BigInt(b)) % MOD_BIG);
