function maxSizeSlices(slices: number[]): number {
    const total = slices.length;
    const picks = total / 3;
    const NEG = -1e15;

    const solve = (arr: number[], k: number): number => {
        const len = arr.length;
        const dp: number[][] = Array.from({ length: len + 1 }, () => Array(k + 1).fill(NEG));
        dp[0][0] = 0;

        for (let i = 1; i <= len; i++) {
            dp[i][0] = 0;

            for (let j = 1; j <= k; j++) {
                dp[i][j] = dp[i - 1][j];

                const prev = i >= 2 ? dp[i - 2][j - 1] : (j === 1 ? 0 : NEG);
                dp[i][j] = Math.max(dp[i][j], prev + arr[i - 1]);
            }
        }

        return dp[len][k];
    };

    return Math.max(
        solve(slices.slice(0, total - 1), picks),
        solve(slices.slice(1), picks)
    );
};
