    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const base = (i * n + j) * 4;
            const ch = grid[i][j];

            if (ch === '/') {
                union(base + 0, base + 3);
                union(base + 1, base + 2);
            } else if (ch === '\\') {
                union(base + 0, base + 1);
                union(base + 2, base + 3);
            } else {
