function medianSlidingWindow(nums: number[], k: number): number[] {
    class Fenwick {
        size: number;
        tree: number[];

        constructor(size: number) {
            this.size = size;
            this.tree = new Array(size + 1).fill(0);
        }

        add(index: number, delta: number): void {
            for (let i = index + 1; i <= this.size; i += i & -i) {
                this.tree[i] += delta;
            }
        }

        kth(order: number): number {
            let idx = 0;
            let bit = 1;

            while ((bit << 1) <= this.size) bit <<= 1;

            for (let step = bit; step > 0; step >>= 1) {
                const next = idx + step;
                if (next <= this.size && this.tree[next] < order) {
                    idx = next;
                    order -= this.tree[next];
                }
            }

            return idx;
        }
    }

    const sorted = nums.slice().sort((a, b) => a - b);
    const values: number[] = [];

    for (const num of sorted) {
        if (values.length === 0 || values[values.length - 1] !== num) {
            values.push(num);
        }
    }

    const indexMap = new Map<number, number>();
    for (let i = 0; i < values.length; i++) {
        indexMap.set(values[i], i);
    }

    const fenwick = new Fenwick(values.length);
    const result: number[] = [];

    for (let i = 0; i < nums.length; i++) {
        fenwick.add(indexMap.get(nums[i])!, 1);

        if (i >= k) {
            fenwick.add(indexMap.get(nums[i - k])!, -1);
        }

        if (i >= k - 1) {
            if (k % 2 === 1) {
                const midIndex = fenwick.kth(Math.floor(k / 2) + 1);
                result.push(values[midIndex]);
            } else {
                const leftIndex = fenwick.kth(k / 2);
                const rightIndex = fenwick.kth(k / 2 + 1);
                result.push((values[leftIndex] + values[rightIndex]) / 2);
            }
        }
    }

    return result;
};
