function minStickers(stickers: string[], target: string): number {
    const INF = 1_000_000;
    const required = new Array<number>(26).fill(0);

    for (const ch of target) {
        required[ch.charCodeAt(0) - 97]++;
    }

    const covered = new Array<boolean>(26).fill(false);
    const stickerCounts: number[][] = [];

    for (const sticker of stickers) {
        const cnt = new Array<number>(26).fill(0);
        let useful = false;

        for (const ch of sticker) {
            const idx = ch.charCodeAt(0) - 97;
            if (required[idx] > 0) {
                cnt[idx]++;
                covered[idx] = true;
                useful = true;
            }
        }

        if (useful) {
            stickerCounts.push(cnt);
        }
    }

    for (let i = 0; i < 26; i++) {
        if (required[i] > 0 && !covered[i]) {
            return -1;
        }
    }

    const removed = new Array<boolean>(stickerCounts.length).fill(false);

    for (let i = 0; i < stickerCounts.length; i++) {
        for (let j = 0; j < stickerCounts.length; j++) {
            if (i === j) continue;

            let dominated = true;
            let strictlyWorse = false;

            for (let k = 0; k < 26; k++) {
                if (stickerCounts[i][k] > stickerCounts[j][k]) {
                    dominated = false;
                    break;
                }
                if (stickerCounts[i][k] < stickerCounts[j][k]) {
                    strictlyWorse = true;
                }
            }

            if (dominated && (strictlyWorse || j < i)) {
                removed[i] = true;
                break;
            }
        }
    }

    const counts = stickerCounts.filter((_, i) => !removed[i]);
    const memo = new Map<string, number>();
    memo.set("", 0);

    const dfs = (remain: string): number => {
        const cached = memo.get(remain);
        if (cached !== undefined) return cached;

        const need = new Array<number>(26).fill(0);
        for (const ch of remain) {
            need[ch.charCodeAt(0) - 97]++;
        }

        const first = remain.charCodeAt(0) - 97;
        let best = INF;

        for (const cnt of counts) {
            if (cnt[first] === 0) continue;

            const nextParts: string[] = [];

            for (let i = 0; i < 26; i++) {
                const left = need[i] - cnt[i];
                if (left > 0) {
                    nextParts.push(String.fromCharCode(97 + i).repeat(left));
                }
            }

            const next = nextParts.join("");
            const sub = dfs(next);

            if (sub !== INF) {
                best = Math.min(best, sub + 1);
            }
        }

        memo.set(remain, best);
        return best;
    };

    const sortedTarget = target.split("").sort().join("");
    const answer = dfs(sortedTarget);

    return answer >= INF ? -1 : answer;
}
