function validateBinaryTreeNodes(n: number, leftChild: number[], rightChild: number[]): boolean {
    const indegree: number[] = new Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        const left = leftChild[i];
        const right = rightChild[i];

        if (left !== -1) {
            indegree[left]++;
            if (indegree[left] > 1) return false;
        }

        if (right !== -1) {
            indegree[right]++;
            if (indegree[right] > 1) return false;
        }
    }

    let root = -1;
    let rootCount = 0;

    for (let i = 0; i < n; i++) {
        if (indegree[i] === 0) {
            root = i;
            rootCount++;
        }
    }

    if (rootCount !== 1) return false;

    const visited: boolean[] = new Array(n).fill(false);
    const stack: number[] = [root];
    let visitedCount = 0;

    while (stack.length > 0) {
        const node = stack.pop()!;

        if (visited[node]) return false;

        visited[node] = true;
        visitedCount++;

        if (leftChild[node] !== -1) stack.push(leftChild[node]);
        if (rightChild[node] !== -1) stack.push(rightChild[node]);
    }

    return visitedCount === n;
};
